 "content": "from collections import Counter


def _components(grid, bg):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = set()
            while stack:
                p = stack.pop()
                cells.add(p)
                x, y = p
                for q in ((x-1, y), (x+1, y), (x, y-1), (x, y+1)):
                    a, b = q
                    if 0 <= a < h and 0 <= b < w and q not in seen and grid[a][b] == color:
                        seen.add(q)
                        stack.append(q)
            result.append((color, cells))
    return result


def transform(grid):
    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    comps = _components(grid, bg)
    guide = None
    for color, cells in comps:
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
        # Find a connected, filled L whose elbow is a bounding-box corner.
        for er, ec in ((r0, c0), (r0, c1), (r1, c0), (r1, c1)):
            expected = ({(er, c) for c in range(c0, c1 + 1)} |
                        {(r, ec) for r in range(r0, r1 + 1)})
            if cells == expected and len(cells) >= 7 and r1-r0 >= 2 and c1-c0 >= 2:
                guide = (color, cells, er, ec, r0, r1, c0, c1)
                break
        if guide is not None:
            break
    if guide is None:
        return out

    color, guide_cells, er, ec, r0, r1, c0, c1 = guide
    # The intended object is in the open quadrant opposite the two L arms.
    vertical_points_up = er == r0
    horizontal_points_left = ec == c1
    targets = []
    for obj_color, cells in comps:
        if cells == guide_cells:
            continue
        if vertical_points_up:
            row_ok = all(r > er for r, c in cells)
        else:
            row_ok = all(r < er for r, c in cells)
        if horizontal_points_left:
            col_ok = all(c > ec for r, c in cells)
        else:
            col_ok = all(c < ec for r, c in cells)
        if row_ok and col_ok:
            distance = min(abs(r-er) + abs(c-ec) for r, c in cells)
            targets.append((distance, len(cells), obj_color, cells))
    if targets:
        _, _, _, cells = min(targets, key=lambda item: (item[0], -item[1]))
        for r, c in cells:
            out[r][c] = color
    return out


if __name__ == '__main__':
    pass
